  ipcMain.handle('app:getSettings', async () => getSettings());
  // ... other handlers
}

// renderer/ipc.ts
export function invokeApp<T>(channel: AppChannels, ...args: any[]): Promise<T> {
  return window.api.invoke(channel, ...args) as Promise<T>;
}

Also add tests that simulate missing handlers.

